-- Gathering 6, generated by scripts/gen-gathering-sql.ts. Do not edit by hand.
insert into public.gathering_scripts (series_id, season_number, week, data) values
('dark-moon', 1, 6, '{"meta":{"dc":11,"ueDc":9,"def":26,"atk":19,"reward":1030,"enemy":"The Faithful & The Hollowed","condition":"Half faithful (the chant: DEF +1 while >50% stand), half hollowed (rises once at 2 HP).","ueAttr":"Aim","ueTitle":"THE HAWSER","barWay":"The Hawser","barRisk":"Your Line"},"steps":[{"t":"tonight","text":"Tonight: the Gathering. Through the Seekers'' door, with the fifth, as the moon goes dark. Tonight calls on Aim.","section":""},{"t":"section","title":"Arrival","section":"Arrival"},{"t":"say","text":"The Seekers'' way in is a crack in the hill behind the hall, so narrow you go through it sideways, so old the stone has healed half shut around it. At its end, the fitted stone that passes for rock swings inward under your hands — for your blood, and no one else''s.","section":"Arrival"},{"t":"act","label":"STRIKE THE LAST STROKE","section":"Arrival"},{"t":"say","text":"{TAPPER} strikes the last stroke through the watch-page by lamplight, there on the threshold. None left.\n\nAbove you, the moon is full. At its edge, a sliver of it has already gone dark, and the dark is spreading.","section":"Arrival"},{"t":"section","title":"The Approach","section":"The Approach"},{"t":"say","text":"Beyond the stone is a passage the Seekers cut for themselves: one turn, then a stair, then the back of the hall.","section":"The Approach"},{"t":"pick","vote":true,"question":"HOW DO YOU GO IN?","options":[{"label":"LAMPS DARK","desc":"unseen, and half blind."},{"label":"LAMPS LIT","desc":"you will see every step, and so will anything that is looking this way."}],"section":"The Approach","mode":"vote"},{"t":"approach","title":"THE SEEKERS'' STAIR","ways":[{"by":"Lamps dark","attr":"Agility","verb":"bring everyone down the stair without a sound"},{"by":"Lamps lit","attr":"Intellect","verb":"read the Seekers'' marks on the wall, and find where they meant a watcher to stand"}],"reward":"+500g · **and the party strikes first**","fail":"a lamp rings on stone, and **they strike first**","section":"The Approach"},{"t":"say","text":"You come out behind a pillar, unseen, with one long breath to take in the hall.","cond":{"on":"approach","pass":true},"section":"The Approach"},{"t":"say","text":"By the time you step out, every face in the hall is already turned toward you.","cond":{"on":"approach","pass":false},"section":"The Approach"},{"t":"section","title":"The Battle","section":"The Battle"},{"t":"say","text":"The hall is vast, and cold, and full.\n\nAcross the floor, a trapdoor stands thrown back on a stair going down into the dark — the way his household ran, the night the Seekers came. The faithful came up it. They didn''t need the Seekers'' door. They are here — more than you''ve ever seen together, robed, singing — and between them stand the hollowed, row on row of them, his soldiers from the last war, still standing their watch after all these centuries. Every blank face turns toward you at once.","section":"The Battle"},{"t":"battle","name":"","firstLines":["You strike first.","They strike first."],"desc":"**ONE OF THE FAITHFUL** · **The chant:** while more than half the faithful are standing, each of them is harder to put down. *or* **ONE OF THE HOLLOWED** · **It does not fall until it is broken:** put down, it gets up once more.","section":"The Battle"},{"t":"section","title":"The United Effort","section":"The United Effort"},{"t":"say","text":"One line of them is left between you and the throne, shoulder to shoulder, still singing. Above them, on a chain as thick as a wrist, hangs the hall''s great iron lamp, dark for centuries.\n\nThe chain runs up over a roof-beam and down the far wall to an iron ring. The last yard of it, where it is tied off, is not chain. It is rope: tarred, black, as thick as an arm, and older than the Order.\n\nYou cannot get to it. You can hit it.\n\nYou are holding a line of your own, and it is all that is keeping theirs off you. One of you can step back out of it for as long as one shot takes. The gap is felt at once.","section":"The United Effort"},{"t":"ue","section":"The United Effort"},{"t":"say","text":"There is a pillar at your back, and it is the only line you have. One step out from it, one shot, and back.","cond":{"on":"alone"},"section":"The United Effort"},{"t":"ueEnd","won":true,"section":"The United Effort"},{"t":"say","text":"The lamp comes down like a bell falling, and the line breaks around it.","cond":{"on":"ue","won":true},"section":"The United Effort"},{"t":"ueEnd","won":false,"section":"The United Effort"},{"t":"say","text":"The chain holds, and you go through them a step at a time, bleeding.","cond":{"on":"ue","won":false},"section":"The United Effort"},{"t":"section","title":"The king","section":"The king"},{"t":"say","text":"When you break through at last, the singing has stopped, and you see what''s at the heart of the hall.\n\nBefore the empty throne, on the stone floor where he fell, lies the king. He isn''t dust. He isn''t bones. He looks like a man asleep — pale, still, one hand open at his side as though something was once taken out of it. *Death''s likeness, and not death.*\n\nAround him, set in a ring, faintly glowing, are the four Stones. Earth, wind, water, fire. Every one you ever found for them.","section":"The king"},{"t":"say","text":"You hold the only missing piece. Right place. Right night. The moon going dark overhead.","section":"The king"},{"t":"act","label":"OPEN YOUR PALM","section":"The king"},{"t":"say","text":"Nothing.","section":"The king"},{"t":"section","title":"The first twist","section":"The first twist"},{"t":"say","text":"The silence is so complete you can hear the last of the faithful breathing in the dark behind you.\n\nGarrick crouches beside whoever is holding the fifth. He looks at the cut palm, at the Stone lying cold in it, at the dust of the long road on them. *\"You''ve carried it far enough,\"* he says.\n\nThen he stands, and holds out his hand. *\"Let me.\"*","section":"The first twist"},{"t":"act","label":"WHY WOULD YOURS WORK?","section":"The first twist","timeout":30},{"t":"say","text":"*\"You''ve all tried tonight,\"* he says. *\"I haven''t.\"*","section":"The first twist","ifTapped":true},{"t":"pick","vote":false,"question":"THE FIFTH IS IN YOUR HANDS.","options":[{"label":"GIVE IT TO HIM","desc":""},{"label":"HOLD IT BACK","desc":""}],"section":"The first twist","mode":"private"},{"t":"say","text":"You hand him the fifth. You do it yourselves.\n\nHe doesn''t hesitate. The knife is already in his hand, and the cut is quick and practised — and the Stone *answers*.","cond":{"on":"pick","option":0},"section":"The first twist"},{"t":"say","text":"He doesn''t argue. The fight has left his palm bleeding. He reaches out and closes his hand over the Stone where it lies in yours — and it answers him anyway. You still carried it to him, into this room.","cond":{"on":"pick","option":1},"section":"The first twist"},{"t":"say","text":"Not a flicker. A flood: cold light pouring up out of it the instant his blood touches it, hungry, as though it has been waiting for this for centuries. Around the king, the four Stones blaze in answer, and the light breaks over the ring like a wave and pins you all where you kneel. You can breathe. You can see. You cannot rise.\n\n*\"The page said the fifth would end this,\"* Garrick says. *\"It never said whose blood.\"*","section":"The first twist"},{"t":"say","text":"The torn page: **\"…drink deep whichever marked blood finds them first. The fifth heeds no element at all, but blood alone, and remembers whose.\"**","section":"The first twist"},{"t":"say","text":"The Verse of the Binding: **\"The fifth drinks deep of moon-blood, and of no other.\"**","section":"The first twist"},{"t":"say","text":"The Seekers, on the wall above the herald''s gate: **\"Four of us gave to the four. None of us gave to the fifth.\"**","section":"The first twist"},{"t":"say","text":"The warning Meira glossed: **\"Moon-blood woke it once. Moon-blood will wake it again, if it is ever let near.\"**","section":"The first twist"},{"t":"say","text":"*\"You read them as one,\"* Garrick says. He doesn''t sound cruel. *\"They cut his name out of everything they could reach. The word outlived him and wandered off onto any child born in the dark. Your Meira used it that way.\"*","section":"The first twist"},{"t":"act","label":"DID YOU EVER LIE TO US?","section":"The first twist"},{"t":"say","text":"*\"No,\"* Garrick says. *\"The faithful don''t.\"*","section":"The first twist"},{"t":"act","label":"MEIRA?","section":"The first twist"},{"t":"say","text":"*\"My people,\"* he says. *\"On the road, the night she left with those pages.\"*\n\nHer pen is in that satchel still.","section":"The first twist"},{"t":"say","text":"Around the ring, the faithful are getting up off the floor. None of them has ever seen his face. They don''t need to: the fifth answered him. One by one they bow their heads to him, and the first of them says it — the words you heard the watchmen trade in the square below this hall.\n\n*\"Keep the dark.\"*\n\n*\"It keeps us,\"* Garrick says.","section":"The first twist"},{"t":"section","title":"The Verse of the Name","section":"The Verse of the Name"},{"t":"say","text":"As the light climbs the four Stones, Garrick takes a book from inside his coat — not a page, not a scrap: his own copy of the Order''s scripture, whole, worn soft with handling, nothing torn, nothing burned. He opens it the way a man opens something his family has kept for generations, and reads.","section":"The Verse of the Name"},{"t":"say","text":"*From the First Book of the Order of the Dark Moon, as his own house kept it — The Verse of the Name.*\n\n*Hear how he came by the name we keep.*\n\n*On the morning of the answering, when the enemy''s camp was only ash and silence, his people came up onto the wall to look at him.*\n\n*They had known him all his life as one of the marked — born in the dark moon''s hour, as many are. That morning they knew the word no longer fit him. The marked carry the moon''s light the way a lamp carries fire. He did not carry it. He had been answered by it. A piece of the moon had drunk of him, and would drink of no one else, ever again — no one but him, and his children, and their children, for as long as his blood ran anywhere under the sky.*","section":"The Verse of the Name"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"They had known him all his life as one of the marked.\"*","source":"From the barracks hearth, on the second day of this week","section":"The Verse of the Name","answer":"6-2"},{"t":"act","label":"READ ON","section":"The Verse of the Name"},{"t":"say","text":"*So they gave him a new name, there on the wall. Not marked. Moon-blood. It was a title, and it was his alone, and after him it was his house''s.*\n\n*When the Seekers came into his hall, his house fled into the night. They let us go. We were only servants, they said. We have been servants ever since — of him, of his sleep, of the long and patient waiting. We kept the old words his house had always kept. We lost not one of them, in all the long dark. And we have never forgotten how they end.*","section":"The Verse of the Name"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"We were only servants, they said.\"*","source":"From the wall room, on the first day of this week","section":"The Verse of the Name","answer":"6-1"},{"t":"say","text":"*\"Bloodlines outlast kingdoms. That is why kingdoms fear them.\"*","alone":true,"section":"The Verse of the Name"},{"t":"say","text":"*His house had kept a thing since before his house had a name.* It was never lost. It was the fifth.","section":"The Verse of the Name"},{"t":"section","title":"The second twist","section":"The second twist"},{"t":"say","text":"He turns the page, and you know it before he reads it: the same page you carried up out of the drowned village, burned and torn. Only his copy is whole.","section":"The second twist"},{"t":"say","text":"**[The older hand, untorn]**\n**\"Four were given to the wind, the water, the fire, and the earth, and drink deep whichever marked blood finds them first. The fifth heeds no element at all, but blood alone, and remembers whose. What the four begin, the fifth shall end, and the throne rise whole.\"**","section":"The second twist"},{"t":"say","text":"He reads it as far as the tear — *what the four begin, the fifth shall end* — and stops, and doesn''t need to go on. All around the hall, low and together, the faithful finish it for him, in the same voice you first heard chanting under the mill hill: *\"…and the throne rise whole.\"*","section":"The second twist"},{"t":"say","text":"*\"They used his own blood on the fifth while his power was pouring out of him,\"* Garrick says, softly, watching the light rise. *\"Tonight he sleeps. Same key. Turned the other way.\"*\n\nHe sets the book down open on the stone. From his coat he takes a tin cup — the one that sat on the sill of the wall room last night — and sets it on the floor beside the sleeping king. Every night on the road, one more cup than there were people. It was always for him.\n\nThen he kneels, and closes the king''s open hand around the fifth Stone — the hand that''s lain empty at his side since the moment he fell. *\"One stayed close,\"* Garrick says. *\"It always did.\"*\n\nAs the fifth leaves his hand, the light shifts to the king — and for one heartbeat, its grip on one of you slackens.","section":"The second twist"},{"t":"section","title":"The act","section":"The act"},{"t":"say","text":"The light lets go of {CHOSEN}. One heartbeat. One act.\n\n**Everyone else: you have thirty seconds. Tell {CHOSEN} what to do.**","section":"The act"},{"t":"pick","vote":false,"question":"","options":[{"label":"TEAR THE PAGE","desc":"snatch the open book from the stone and rip the untorn page out of it."},{"label":"BREAK THE RING","desc":"strike one of the four Stones out of the ring."},{"label":"DO NOTHING","desc":""}],"section":"The act","mode":"chosen"},{"t":"say","text":"It''s done before anyone can stop it. The page is in {CHOSEN}''s fist.","cond":{"on":"pick","option":0},"section":"The act"},{"t":"say","text":"It skids across the floor, still glowing, out of the light and away into the dark of the hall.","cond":{"on":"pick","option":1},"section":"The act"},{"t":"say","text":"*\"Your Seekers made their children the only key,\"* Garrick says, looking down at you from the king''s side. *\"The key that locks is also the key that unlocks.\"* A breath. *\"You were the key.\"*","section":"The act"},{"t":"say","text":"*\"If you are reading this, you are ours — and if he ever stirs, finish what we could not.\"*","alone":true,"section":"The act"},{"t":"section","title":"The Cliffhanger","section":"The Cliffhanger"},{"t":"say","text":"Overhead, the last of the moon goes dark.\n\nThe four Stones flare white. The fifth, in the king''s closed hand, burns so cold it frosts the air.","section":"The Cliffhanger"},{"t":"say","text":"And on the floor of his hall, where he fell, the king opens his eyes.\n\nThey pass over Garrick, kneeling at his side, as if he weren''t there. They move across the ring of light. And they settle on you. Whatever he is now, he knows Seeker blood when he sees it.\n\n*The power that gives is also the power that takes.*\n\nGarrick looks down at you — at all of you, kneeling in the ring of light, palms cut, still bleeding, the same white linen from a week ago still knotted at every wrist. His face is courteous, and nothing more.\n\n*\"You saved every child you were sent to save,\"* he says.","section":"The Cliffhanger"},{"t":"pick","vote":false,"question":"SAY A NAME.","options":[{"label":"TAMSIN","desc":""},{"label":"CORIN","desc":""},{"label":"WREN","desc":""},{"label":"JOSS","desc":""}],"section":"The Cliffhanger","mode":"each"},{"t":"say","text":"**Tamsin,** humming her counting song so she wouldn''t cry.","section":"The Cliffhanger","nameOf":0},{"t":"say","text":"**Corin,** saying your names back to keep them.","section":"The Cliffhanger","nameOf":1},{"t":"say","text":"**Wren,** pressing a chip of black glass into your palm.","section":"The Cliffhanger","nameOf":2},{"t":"say","text":"**Joss,** holding on to his little boat.","section":"The Cliffhanger","nameOf":3},{"t":"section","title":"The last notice","section":"The last notice"},{"t":"notice","lines":{"Might":"The light holds you by nothing you can push against. For the first time since the forest road, strength is not what is being asked of you.","Agility":"The trapdoor his household ran by is still standing open, twenty paces behind the faithful. Nobody is watching it.","Intellect":"He knew Seeker blood the moment he saw it. Nobody has yet told him how long he slept.","Charm":"He is looking at each of you in turn, the way Corin did. As if to keep you.","Craft":"The knot at your wrist is the one at Tamsin''s. You watched it tied a week ago, and thought nothing of it.","Aim":"Through the high windows there is no moon at all. Not a rim of it."},"section":"The last notice"},{"t":"section","title":"The last lines","section":"The last lines"},{"t":"say","text":"Tamsin''s hand. Corin''s. Wren''s. Joss''s. Yours. The same linen. The same careful knot, every time.\n\n**To be continued.**","section":"The last lines"},{"t":"summary","lines":["**HIS HALL** · Gathering 6","{EARNED}","The party: Battle {battle} · the lamp {ue:down|held} · the fifth {pick:31:given|held back} · the act: {pick:61:the page torn|the ring broken|nothing}","You learned: **moon-blood was never a word for you.** It was the king''s title, and then his house''s. Garrick is the last of that house, and the Order is his. He never lied to you. His people killed Meira. The fifth did not stop the waking; it finished it. The king is awake, and he is looking at you.","You saved every child you were sent to save.","What you did in that last heartbeat is remembered. Season 2 begins from it.","**Unlocked: Garrick''s Recap.** Every line he ever said to you, to read again."],"section":"The last lines"}],"ue":{"success":{"0":["It parts."],"1":["It is singing: one thin note, under theirs.","One strand. You can see the light through it."],"2":["Half of it is hanging in tatters. The rest is drawn as tight as a bowstring.","The lamp is swinging now, slow, the width of a man."],"3":["It goes in where the rope bends over the ring. A strand springs loose and stands out from it like a hair.","Another strand. High above the singing line, the great lamp turns a little on its chain."]},"fail":{"0":["There is nowhere left to shoot from."],"1":["Your backs are almost against the pillars.","There is no room left to step back into."],"2":["Somebody takes a blow that was meant for the gap you left.","You loose with a hollowed face a sword''s length from yours."],"3":["Wide. It rings on the iron ring and is gone into the dark. While you were aiming, the line took a step.","You hit the stone a hand''s breadth from it. The place you left in your own line has closed up, a yard further back than it was."]},"between":["They have not stopped singing. They have not once looked up.","Beyond their line, on the floor before the throne, something is giving off a faint light."]}}'::jsonb)
on conflict (series_id, season_number, week) do update set data = excluded.data;
